op = urllib.request.build_opener(NoRedirect)
pg = op.open(BASE + "/login.php", timeout=20)
sc = pg.headers.get_all("Set-Cookie") or []
body = pg.read().decode()
tok = re.search(r"user_token' value='([0-9a-f]+)'", body).group(1)
cookies = {}
for c in sc:
